
/*
 * ==========================================================
 * ARCHINEL — MOCK SCANNING ENGINE
 *
 * IMPORTANT:
 * All results generated by this file are MOCK DATA.
 * No real website is scanned.
 * No external threat intelligence is consulted.
 * No actual security verdict is produced.
 *
 * This module is temporary and will later be replaced
 * by the real scanning API without changing the result shape.
 * ==========================================================
 */

// Wait for a random duration between 1 and 2 seconds.
function delay() {
  const duration = 1000 + Math.floor(Math.random() * 1001);

  return new Promise((resolve) => {
    setTimeout(resolve, duration);
  });
}

// Deterministic 32-bit hash.
// The same normalised URL always produces the same hash.
function hashURL(value) {
  let hash = 2166136261;

  for (let index = 0; index < value.length; index++) {
    hash ^= value.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }

  return hash >>> 0;
}

// Convert a numerical score into a severity.
function getSeverity(score) {
  if (score >= 85) return "Critical";
  if (score >= 65) return "High";
  if (score >= 40) return "Medium";

  return "Low";
}

// Generate a verdict based on the mock score.
function getVerdict(score) {
  return score >= 40 ? "Risky" : "Safe";
}

// Generate short, human-readable MOCK explanations.
function getReasons(type, severity) {
  const commonReason =
    "This is a simulated result. No live security investigation was performed.";

  if (type === "malicious") {
    return [
      "Test trigger detected: URL contains a malicious keyword.",
      "A high-risk scenario has been simulated.",
      commonReason,
    ];
  }

  if (type === "phishing") {
    return [
      "Test trigger detected: URL contains a phishing keyword.",
      "A high-risk phishing scenario has been simulated.",
      commonReason,
    ];
  }

  if (type === "safe") {
    return [
      "Test trigger detected: URL contains the example-safe marker.",
      "A low-risk demonstration scenario has been assigned.",
      commonReason,
    ];
  }

  return [
    "Risk score generated using a deterministic URL hash.",
    `The simulated result falls into the ${severity} severity category.`,
    commonReason,
  ];
}

// Classify URL input and generate its mock score.
function generateMockAssessment(url) {
  const lowerURL = url.toLowerCase();

  let score;
  let type;

  if (lowerURL.includes("malicious")) {
    score = 96;
    type = "malicious";
  } else if (lowerURL.includes("phish")) {
    score = 89;
    type = "phishing";
  } else if (lowerURL.includes("example-safe")) {
    score = 8;
    type = "safe";
  } else {
    const hash = hashURL(url);

    // Deterministic score between 10 and 90.
    score = 10 + (hash % 81);
    type = "default";
  }

  const severity = getSeverity(score);
  const verdict = getVerdict(score);

  return {
    score,
    severity,
    verdict,
    reasons: getReasons(type, severity),
  };
}

/*
 * ==========================================================
 * MAIN MOCK SCAN FUNCTION
 *
 * Expected future API response shape:
 *
 * {
 *   id,
 *   url,
 *   domain,
 *   score,
 *   severity,
 *   verdict,
 *   reasons,
 *   scannedAt,
 *   source
 * }
 * ==========================================================
 */

export async function mockScan(url) {
  if (typeof url !== "string" || !url.trim()) {
    throw new Error("Please provide a valid website URL.");
  }

  let parsedURL;

  try {
    parsedURL = new URL(url.trim());
  } catch {
    throw new Error("The website URL is invalid. Please check it and try again.");
  }

  if (
    !["http:", "https:"].includes(parsedURL.protocol) ||
    !parsedURL.hostname ||
    parsedURL.username ||
    parsedURL.password
  ) {
    throw new Error("Only valid HTTP or HTTPS website URLs are supported.");
  }

  // Normalise the URL before generating its result.
  const normalisedURL = parsedURL.href;
  const lowerURL = normalisedURL.toLowerCase();

  // Simulate the time taken by an investigation.
  await delay();

  // Special trigger for testing the error state.
  if (lowerURL.includes("fail")) {
    throw new Error(
      "The mock investigation failed. Please try scanning another URL."
    );
  }

  const assessment = generateMockAssessment(normalisedURL);

  return {
    id: `MOCK-${Date.now().toString(36)}-${hashURL(normalisedURL).toString(36)}`,
    url: normalisedURL,
    domain: parsedURL.hostname,
    score: assessment.score,
    severity: assessment.severity,
    verdict: assessment.verdict,
    reasons: assessment.reasons,
    scannedAt: new Date().toISOString(),
    source: "Mock",
  };
}
